const D = { scale:1, energy:.6, hue:290, speed:1, density:.5, x:.5, y:.5, tentacles:.55, bell:.55, seed:0, pose:'auto', style:'biolum', act:'bloom' };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

const fr = i => { const q = Math.sin(i*127.1 + P.seed*311.7)*43758.5453; return q - Math.floor(q); };
const u = Math.min(width, height);
const TAU = Math.PI*2;
const bt = K.beat * P.speed;
const eAmp = P.energy*(.5 + .6*K.intensity);
S.rms = (S.rms||0)*.85 + (A.rms||0)*.15;
S.tre = (S.tre||0)*.8  + (A.treble||0)*.2;
const hue = ((P.hue%360)+360)%360;
const st = P.style;

// ---- bell contraction ON the beat ----
// K.pulse spikes to 1 on beat then decays -> jet-propulsion contraction
const beat = Math.min(1.3, K.pulse*(0.65+0.5*K.intensity) + A.bass*0.7);
const R = u * 0.20 * P.scale * (0.85 + 0.45*P.bell);   // bell radius
const contract = beat * (0.28 + 0.15*eAmp);            // radial contraction amount
const bellW = R * (1 - 0.42*contract);                 // squashed wide on contract
const bellH = R * (0.72 + 0.55*contract);              // taller on contract

// ---- pose / dramaturgy ----
let pose = P.pose;
if (pose === 'auto') {
  const ACT = { bloom:['drift','pulse','pulse','drift'], hunt:['spin','pulse','spin','pulse'], float:['drift','drift','float','drift'] };
  const seq = ACT[P.act] || ACT.bloom; pose = seq[(((K.section%seq.length)+seq.length)%seq.length)];
}
// propulsion: each contraction thrusts the bell up, then it sinks (buoyancy)
if (S.py == null) { S.py = P.y*height; S.vy = 0; }
if (S.lastBeat == null || K.beat < S.lastBeat) S.lastBeat = K.beat;
S.vy += beat * -u*0.010 * (0.6+eAmp);          // thrust up on pulse
S.vy += u*0.0016;                               // gravity/sink
S.vy *= 0.90;
S.py += S.vy;
const anchorY = P.y*height + (pose==='float'? Math.sin(K.t*0.4)*u*0.02 : 0);
S.py += (anchorY - S.py)*0.02;                  // tether toward anchor
let cx = P.x*width + Math.sin(K.t*0.3 + fr(2)*6)*u*0.03*(pose==='drift'?1:0.4);
let spin = 0;
if (pose==='spin') spin = bt*0.35*eAmp;
else spin = Math.sin(K.t*0.5)*0.12;
const cy = S.py;

// ---- tentacle trail physics (verlet strands under S, seed-det) ----
const NT = Math.round(6 + 12*P.tentacles);      // marginal tentacles
const SEG = 9;
const tlen = R*(1.6 + 2.2*P.tentacles);
if (S.seedUsed !== P.seed || !S.ten || S.tenN !== NT) {
  S.seedUsed = P.seed; S.tenN = NT; S.ten = [];
  for (let i=0;i<NT;i++){ const strand=[]; for (let j=0;j<SEG;j++) strand.push({x:cx, y:cy, px:cx, py:cy}); S.ten.push(strand); }
}
const oralN = Math.round(3 + 6*P.density);
if (!S.oral || S.oralN !== oralN){ S.oralN=oralN; S.oral=[]; for (let i=0;i<oralN;i++){ const strand=[]; for(let j=0;j<7;j++) strand.push({x:cx,y:cy,px:cx,py:cy}); S.oral.push(strand);} }

function stepStrand(strand, ax, ay, spread, seg, len, stiff, cur){
  strand[0].x = ax; strand[0].y = ay;
  for (let j=1;j<seg;j++){
    const n=strand[j]; const vx=(n.x-n.px)*0.86, vy=(n.y-n.py)*0.86; n.px=n.x; n.py=n.y;
    n.x += vx + cur; n.y += vy + u*0.0011*(0.6+eAmp);   // drift + slight current
  }
  const dl = len/seg;
  for (let k=0;k<3;k++) for (let j=1;j<seg;j++){
    const a=strand[j-1], b=strand[j]; let dx=b.x-a.x, dy=b.y-a.y; let d=Math.hypot(dx,dy)||0.0001;
    const diff=(d-dl)/d*stiff; const mx=dx*diff*(j===1?1:0.5), my=dy*diff*(j===1?1:0.5);
    if (j>1){ a.x+=mx; a.y+=my; } b.x-=mx; b.y-=my;
  }
}

const cur = Math.sin(K.t*0.7)*u*0.0016*(0.5+eAmp) + S.tre*u*0.004;

// ---- draw ----
push();
translate(cx, cy);
rotate(spin);

// glow halo (few soft shapes)
if (st==='biolum'||st==='iridescent'){
  blendMode(ADD);
  drawingContext.shadowBlur = u*0.06; drawingContext.shadowColor = color(hue,70,90,50);
  noStroke(); fill(hue, 60, 70, 8+10*beat); ellipse(0, 0, bellW*2.4, bellH*2.6);
  drawingContext.shadowBlur = 0; blendMode(BLEND);
}
pop();

// ---- tentacles (drawn in world space, anchored around bell margin) ----
const marginY = cy + bellH*0.55;
for (let i=0;i<NT;i++){
  const ang = (i/NT - 0.5);
  const ax = cx + Math.cos(spin)*ang*bellW*1.9;
  const ay = marginY + Math.sin(ang*3)*bellH*0.06;
  const swayC = cur + Math.sin(K.t*1.1 + i*0.7)*u*0.0016*eAmp;
  stepStrand(S.ten[i], ax, ay, 0, SEG, tlen*(0.7+0.6*fr(i)), 0.9, swayC);
  const strand = S.ten[i];
  if (st==='wireframe'){ stroke(hue, 30, 90, 60); strokeWeight(u*0.0012); }
  else if (st==='xray'){ stroke(hue, 12, 88, 40); strokeWeight(u*0.0012); }
  else if (st==='ink'){ stroke(hue, 8, 78, 42); strokeWeight(u*0.0016*(1+fr(i))); }
  else { stroke(hue, 55, 95, 34+20*beat); strokeWeight(u*0.0016); }
  noFill();
  beginShape(); curveVertex(strand[0].x,strand[0].y);
  for (const nd of strand) curveVertex(nd.x, nd.y);
  const last=strand[SEG-1]; curveVertex(last.x,last.y); endShape();
  if (st==='biolum'){ // bright bead tips
    blendMode(ADD); noStroke(); fill(hue, 40, 100, 40); ellipse(last.x,last.y, u*0.008, u*0.008); blendMode(BLEND);
  }
}

// ---- oral arms (frilly central, shorter, thicker) ----
for (let i=0;i<oralN;i++){
  const ang=(i/oralN-0.5)*0.9;
  const ax=cx + Math.cos(spin)*ang*bellW*0.7, ay=cy+bellH*0.3;
  stepStrand(S.oral[i], ax, ay, 0, 7, tlen*0.45, 0.85, cur*0.7 + Math.sin(K.t*1.4+i)*u*0.0014);
  const s2=S.oral[i];
  if (st==='wireframe'){ stroke(hue,40,90,55); strokeWeight(u*0.0018); noFill(); }
  else if (st==='xray'){ stroke(hue,14,90,48); strokeWeight(u*0.0022); noFill(); }
  else if (st==='ink'){ stroke(hue,10,70,50); strokeWeight(u*0.004*(1+0.5*fr(i))); noFill(); }
  else { stroke(hue,45,95,30+18*beat); strokeWeight(u*0.004); noFill(); }
  beginShape(); curveVertex(s2[0].x,s2[0].y); for(const nd of s2) curveVertex(nd.x,nd.y); const lz=s2[6]; curveVertex(lz.x,lz.y); endShape();
}

// ---- bell ----
push();
translate(cx, cy);
rotate(spin);
function bellPath(sc){
  beginShape();
  const N=22;
  for (let i=0;i<=N;i++){ const a=map(i,0,N,-Math.PI,0); // top dome
    const x=Math.cos(a)*bellW*sc; const y=Math.sin(a)*bellH*sc; curveVertex(x,y); }
  // scalloped margin
  const lobes=NT;
  for (let i=0;i<=lobes;i++){ const fx=map(i,0,lobes,1,-1); const x=fx*bellW*sc; const y=bellH*sc*(0.02 + 0.10*Math.abs(Math.sin(i*1.3))); curveVertex(x, y); }
  endShape(CLOSE);
}

if (st==='wireframe'){
  noFill();
  stroke(hue, 35, 92, 80); strokeWeight(u*0.0016); bellPath(1.0);
  stroke(hue, 35, 92, 45); strokeWeight(u*0.0011);
  for (let r=0.75;r>0.15;r-=0.2) bellPath(r);                 // concentric rings
  for (let i=0;i<NT;i++){ const a=map(i,0,NT-1,-Math.PI*0.92,-0.08); line(0,0, Math.cos(a)*bellW, Math.sin(a)*bellH*0.98); } // radial spokes
} else if (st==='xray'){
  noStroke(); fill(hue, 18, 55, 16); bellPath(1.0);
  stroke(hue, 12, 90, 55); strokeWeight(u*0.0014); noFill(); bellPath(1.0);
  // radial canals + ring
  stroke(hue, 20, 92, 46);
  for (let i=0;i<8;i++){ const a=map(i,0,8,-Math.PI*0.9,-0.1); line(0,-bellH*0.1, Math.cos(a)*bellW*0.92, Math.sin(a)*bellH*0.9); }
  noFill(); ellipse(0,-bellH*0.05, bellW*1.5, bellH*1.3);
  // gonads
  noStroke(); fill(hue,30,80,40); for(let i=0;i<4;i++){ const a=map(i,0,4,-2.4,-0.7); ellipse(Math.cos(a)*bellW*0.45, Math.sin(a)*bellH*0.4-bellH*0.1, bellW*0.16, bellH*0.16);}
} else if (st==='ink'){
  noStroke(); fill(hue, 6, 74, 40); bellPath(1.02);
  fill(hue, 10, 40, 30);
  drawingContext.save(); bellPath(1.0); drawingContext.clip();
  rect(-bellW, -bellH*1.1, bellW*2, bellH*0.8); drawingContext.restore();     // dark dome wash
  stroke(hue, 10, 20, 60); strokeWeight(u*0.0022); noFill(); bellPath(1.0);
} else if (st==='iridescent'){
  drawingContext.save(); bellPath(1.0); drawingContext.clip();
  noStroke(); blendMode(SCREEN);
  for (let i=0;i<7;i++){ const oh=(hue + i*24 + K.t*20)%360; fill(oh, 55, 70, 16); ellipse(Math.sin(i*1.7+K.t)*bellW*0.4, -bellH*0.3 + i*bellH*0.12, bellW*1.6, bellH*0.5); }
  blendMode(BLEND); drawingContext.restore();
  noFill(); stroke(hue, 30, 96, 70); strokeWeight(u*0.0018); bellPath(1.0);
} else {
  // biolum (default): translucent luminous dome, internal gradient, bright rim
  blendMode(ADD);
  noStroke();
  const gstep=0.22-0.12*P.density;                                                              // denser glow ~ density
  for (let r=1.0;r>0.2;r-=gstep){ fill(hue, 65 - r*20, 55 + r*35, 7 + 6*beat); bellPath(r); }   // stacked glow
  // apex core
  fill((hue+20)%360, 40, 100, 16+16*beat); ellipse(0, -bellH*0.35, bellW*0.5, bellH*0.4);
  blendMode(BLEND);
  noFill(); stroke(hue, 50, 100, 55+30*beat); strokeWeight(u*0.0018*(1+0.5*beat)); bellPath(1.0);
  // internal radial fibers
  stroke(hue, 45, 90, 22); strokeWeight(u*0.001);
  for (let i=0;i<NT;i++){ const a=map(i,0,NT-1,-Math.PI*0.9,-0.1); line(0,-bellH*0.1, Math.cos(a)*bellW*0.9, Math.sin(a)*bellH*0.85); }
}
pop();

blendMode(BLEND);
